<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $challan->challan_number }}</title><style>body{font-family:Arial,sans-serif;margin:32px;color:#111}h1{margin:0 0 4px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #999;padding:8px;text-align:left}th{background:#f3f3f3}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:20px}.sign{margin-top:70px;display:grid;grid-template-columns:1fr 1fr;gap:80px}.line{border-top:1px solid #333;padding-top:8px}@media print{body{margin:12mm}.no-print{display:none}}</style></head><body><h1>DELIVERY CHALLAN</h1><div>{{ $challan->challan_number }}</div><div class="meta"><div><b>Delivery Challan For:</b> {{ $challan->delivery_challan_for }}</div><div><b>Shipping To:</b> {{ $challan->shipping_to }}</div><div><b>Customer:</b> {{ $challan->customer->company_name }}</div><div><b>Delivery Date:</b> {{ $challan->delivery_date?->format('d-M-Y') ?? '—' }}</div><div><b>Invoice:</b> {{ $challan->invoice?->invoice_number ?? '—' }}</div><div><b>Shipped Date:</b> {{ $challan->shipped_date?->format('d-M-Y') ?? '—' }}</div></div><table><thead><tr><th>Sr. No.</th><th>Item Name</th><th>Serial # / Service Tag</th><th>Quantity</th><th>Unit</th></tr></thead><tbody>@foreach($challan->items as $item)<tr><td>{{ $item->line_no }}</td><td>{{ $item->item_name }}</td><td>{{ $item->serial_number ?: '—' }}</td><td>{{ rtrim(rtrim(number_format($item->quantity,4,'.',''),'0'),'.') }}</td><td>{{ $item->unit }}</td></tr>@endforeach</tbody></table>@if($challan->terms)<h3>Terms & Conditions</h3><div>{!! nl2br(e($challan->terms)) !!}</div>@endif<div class="sign"><div class="line">Delivered By / Name / Date / Signature</div><div class="line">Received By / Name / Date / Signature</div></div><button class="no-print" onclick="window.print()">Print</button></body></html>
